import sys
sys.setrecursionlimit(20000)
def solve():
    r, c = map(int, input().split())
    grid = [list(map(int, input().split())) for _ in range(r)]
    def dfs(i, j):
        if i<0 or i>=r or j<0 or j>=c or grid[i][j]==0: return
        grid[i][j] = 0
        dfs(i+1,j); dfs(i-1,j); dfs(i,j+1); dfs(i,j-1)
    islands = 0
    for i in range(r):
        for j in range(c):
            if grid[i][j] == 1:
                islands += 1
                dfs(i, j)
    print(islands)

