import java.util.*;
public class Main {
    static boolean dfs(char[][] b, String w, int i, int j, int k) {
        if(k==w.length()) return true;
        if(i<0||i>=b.length||j<0||j>=b[0].length||b[i][j]!=w.charAt(k)) return false;
        char tmp = b[i][j];
        b[i][j] = '#';
        boolean res = dfs(b,w,i+1,j,k+1)||dfs(b,w,i-1,j,k+1)||dfs(b,w,i,j+1,k+1)||dfs(b,w,i,j-1,k+1);
        b[i][j] = tmp;
        return res;
    }
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if(!sc.hasNextInt()) return;
        int r = sc.nextInt(), c = sc.nextInt();
        char[][] b = new char[r][c];
        for(int i=0; i<r; i++) {
            String s = sc.next();
            for(int j=0; j<c; j++) b[i][j] = s.charAt(j);
        }
        String w = sc.next();
        for(int i=0; i<r; i++) {
            for(int j=0; j<c; j++) {
                if(dfs(b,w,i,j,0)) { System.out.println("True"); return; }
            }
        }
        System.out.println("False");
    }
}

