#include <iostream>
#include <vector>
#include <string>
using namespace std;
struct TrieNode { TrieNode* ch[26]={}; string word=""; };
void insert(TrieNode* r, string w) { for(char c:w) { if(!r->ch[c-'a']) r->ch[c-'a']=new TrieNode(); r=r->ch[c-'a']; } r->word=w; }
void dfs(vector<string>& b, int i, int j, TrieNode* p, int& ans) {
    if(i<0||j<0||i>=b.size()||j>=b[0].size()) return;
    char c = b[i][j];
    if(c=='#' || !p->ch[c-'a']) return;
    p = p->ch[c-'a'];
    if(p->word!="") { ans++; p->word=""; }
    b[i][j] = '#';
    dfs(b, i+1, j, p, ans); dfs(b, i-1, j, p, ans); dfs(b, i, j+1, p, ans); dfs(b, i, j-1, p, ans);
    b[i][j] = c;
}
int main() {
    int r,c; if(!(cin>>r>>c)) return 0;
    vector<string> b(r);
    for(int i=0; i<r; i++) cin>>b[i];
    int w; cin>>w;
    TrieNode* root = new TrieNode();
    for(int i=0; i<w; i++) { string s; cin>>s; insert(root, s); }
    int ans = 0;
    for(int i=0; i<r; i++) for(int j=0; j<c; j++) dfs(b, i, j, root, ans);
    cout << ans << endl;
    return 0;
}

