                if(p[j-1]=='.' || p[j-1]==s[i-1]) dp[i][j] = dp[i-1][j-1];
                else if(p[j-1]=='*') {
                    dp[i][j] = dp[i][j-2];
                    if(p[j-2]=='.' || p[j-2]==s[i-1]) dp[i][j] = dp[i][j] || dp[i-1][j];
                }
